// NewKubeMacPoolPrometheusRulePrometheusRulesClusterNetworkAddonsOperator creates the rendered PrometheusRule "prometheus-rules-cluster-network-addons-operator" for the kubeMacPool output.
func NewKubeMacPoolPrometheusRulePrometheusRulesClusterNetworkAddonsOperator() *monitoringv1.PrometheusRule {
	return ptr.To(monitoringv1.PrometheusRule{
		ObjectMeta: metav1.ObjectMeta{
			Name:      "prometheus-rules-cluster-network-addons-operator",
			Namespace: "openshift-cnv",
			Labels: map[string]string{
				"prometheus.cnao.io": "true",
			},
		},
		Spec: monitoringv1.PrometheusRuleSpec{
			Groups: []monitoringv1.RuleGroup{
				{
					Name: "recordingRules.rules",
					Rules: []monitoringv1.Rule{
						{
							Record: "cluster:kubevirt_cnao_cr_kubemacpool_deployed:sum",
							Expr:   intstr.FromString("sum(kubevirt_cnao_cr_kubemacpool_deployed{namespace='openshift-cnv'} or vector(0))"),
						},
						{
							Record: "cluster:kubevirt_cnao_kubemacpool_manager_up:sum",
							Expr:   intstr.FromString("sum(up{namespace='openshift-cnv', pod=~'kubemacpool-mac-controller-manager-.*'} or vector(0))"),
						},
						{
							Record: "cluster:kubevirt_cnao_operator_up:sum",
							Expr:   intstr.FromString("sum(up{namespace='openshift-cnv', pod=~'cluster-network-addons-operator-.*'} or vector(0))"),
						},
						{
							Record: "kubevirt_cnao_cr_kubemacpool_aggregated",
							Expr:   intstr.FromString("sum(kubevirt_cnao_cr_kubemacpool_deployed{namespace='openshift-cnv'} or vector(0))"),
						},
						{
							Record: "kubevirt_cnao_kubemacpool_duplicate_macs",
							Expr:   intstr.FromString("sum(kubevirt_kmp_duplicate_macs{namespace='openshift-cnv'} or vector(0))"),
						},
						{
							Record: "kubevirt_cnao_kubemacpool_manager_up",
							Expr:   intstr.FromString("sum(up{namespace='openshift-cnv', pod=~'kubemacpool-mac-controller-manager-.*'} or vector(0))"),
						},
						{
							Record: "kubevirt_cnao_operator_up",
							Expr:   intstr.FromString("sum(up{namespace='openshift-cnv', pod=~'cluster-network-addons-operator-.*'} or vector(0))"),
						},
					},
				},
				{
					Name: "alerts.rules",
					Rules: []monitoringv1.Rule{
						{
							Alert: "CnaoDown",
							Expr:  intstr.FromString("cluster:kubevirt_cnao_operator_up:sum == 0"),
							For:   ptr.To(monitoringv1.Duration("5m")),
							Labels: map[string]string{
								"kubernetes_operator_component": "cluster-network-addons-operator",
								"kubernetes_operator_part_of":   "kubevirt",
								"operator_health_impact":        "warning",
								"severity":                      "warning",
							},
							Annotations: map[string]string{
								"runbook_url": "https://kubevirt.io/monitoring/runbooks/CnaoDown",
								"summary":     "CNAO pod is down.",
							},
						},
						{
							Alert: "KubemacpoolDown",
							Expr:  intstr.FromString("cluster:kubevirt_cnao_cr_kubemacpool_deployed:sum == 1 and cluster:kubevirt_cnao_kubemacpool_manager_up:sum == 0"),
							For:   ptr.To(monitoringv1.Duration("5m")),
							Labels: map[string]string{
								"kubernetes_operator_component": "cluster-network-addons-operator",
								"kubernetes_operator_part_of":   "kubevirt",
								"operator_health_impact":        "critical",
								"severity":                      "critical",
							},
							Annotations: map[string]string{
								"runbook_url": "https://kubevirt.io/monitoring/runbooks/KubemacpoolDown",
								"summary":     "KubeMacpool is deployed by CNAO CR but KubeMacpool pod is down.",
							},
						},
						{
							Alert: "NetworkAddonsConfigNotReady",
							Expr:  intstr.FromString("sum(kubevirt_cnao_cr_ready{namespace='openshift-cnv'} or vector(0)) == 0"),
							For:   ptr.To(monitoringv1.Duration("5m")),
							Labels: map[string]string{
								"kubernetes_operator_component": "cluster-network-addons-operator",
								"kubernetes_operator_part_of":   "kubevirt",
								"operator_health_impact":        "warning",
								"severity":                      "warning",
							},
							Annotations: map[string]string{
								"runbook_url": "https://kubevirt.io/monitoring/runbooks/NetworkAddonsConfigNotReady",
								"summary":     "CNAO CR NetworkAddonsConfig is not ready.",
							},
						},
					},
				},
			},
		},
	})
}

